import { useEffect, useState } from "react";
import {
  SimpleTreeView,
  TreeItem,
} from "@mui/x-tree-view";
import {
  ApartmentOutlined,
  CropOriginalOutlined,
  LocationCityOutlined,
} from "@mui/icons-material";
import { Box, CircularProgress, Typography } from "@mui/material";
import { api } from "@/api/client";
import type { BuildingSummary, NeighborhoodStats, TreeSelection } from "@/types";

interface DatasetTreeProps {
  dataset: string;
  onSelect: (selection: TreeSelection) => void;
}

// Lazily-loaded building images are stored in a map keyed by building_id
// (they are fetched in BuildingPanel, not here — the tree only needs summaries)

export function DatasetTree({ dataset, onSelect }: DatasetTreeProps) {
  const [neighborhoods, setNeighborhoods] = useState<NeighborhoodStats[]>([]);
  const [buildings, setBuildings] = useState<Record<string, BuildingSummary[]>>({});
  const [loadingHoods, setLoadingHoods] = useState(true);
  const [loadingBuildings, setLoadingBuildings] = useState<Set<string>>(new Set());
  const [expandedHoods, setExpandedHoods] = useState<Set<string>>(new Set());

  // Reload when dataset changes
  useEffect(() => {
    setNeighborhoods([]);
    setBuildings({});
    setExpandedHoods(new Set());
    setLoadingHoods(true);
    api
      .listNeighborhoods(dataset)
      .then(setNeighborhoods)
      .catch(console.error)
      .finally(() => setLoadingHoods(false));
  }, [dataset]);

  function handleExpandedChange(_event: React.SyntheticEvent, nodeIds: string[]) {
    const newlyExpanded = nodeIds.filter((id) => !expandedHoods.has(id));
    setExpandedHoods(new Set(nodeIds));

    for (const nodeId of newlyExpanded) {
      // node IDs for neighbourhoods are "hood:{name}"
      if (!nodeId.startsWith("hood:")) continue;
      const hood = nodeId.slice(5);
      if (buildings[hood]) continue; // already loaded

      setLoadingBuildings((prev) => new Set(prev).add(hood));
      api
        .listBuildings(dataset, hood)
        .then((data) => setBuildings((prev) => ({ ...prev, [hood]: data })))
        .catch(console.error)
        .finally(() =>
          setLoadingBuildings((prev) => {
            const next = new Set(prev);
            next.delete(hood);
            return next;
          })
        );
    }
  }

  if (loadingHoods) {
    return (
      <Box sx={{ p: 2, display: "flex", alignItems: "center", gap: 1 }}>
        <CircularProgress size={16} />
        <Typography variant="body2" color="text.secondary">
          Loading…
        </Typography>
      </Box>
    );
  }

  return (
    <SimpleTreeView
      onExpandedItemsChange={handleExpandedChange}
      sx={{ p: 1 }}
    >
      {neighborhoods.map((hood) => (
        <TreeItem
          key={`hood:${hood.neighborhood}`}
          itemId={`hood:${hood.neighborhood}`}
          label={
            <Box
              sx={{ display: "flex", alignItems: "center", gap: 0.5, py: 0.25 }}
              onClick={() =>
                onSelect({ type: "neighborhood", dataset, neighborhood: hood.neighborhood })
              }
            >
              <LocationCityOutlined fontSize="small" color="action" />
              <Typography variant="body2" fontWeight={500}>
                {hood.neighborhood}
              </Typography>
              <Typography variant="caption" color="text.secondary" sx={{ ml: "auto" }}>
                {hood.building_count}
              </Typography>
            </Box>
          }
        >
          {loadingBuildings.has(hood.neighborhood) ? (
            <TreeItem
              itemId={`loading:${hood.neighborhood}`}
              label={<CircularProgress size={12} sx={{ my: 0.5 }} />}
            />
          ) : (
            (buildings[hood.neighborhood] ?? []).map((building) => (
              <TreeItem
                key={`bldg:${building.building_id}`}
                itemId={`bldg:${building.building_id}`}
                label={
                  <Box
                    sx={{ display: "flex", alignItems: "center", gap: 0.5, py: 0.25 }}
                    onClick={() =>
                      onSelect({
                        type: "building",
                        dataset,
                        building_id: building.building_id,
                      })
                    }
                  >
                    <ApartmentOutlined fontSize="small" color="action" />
                    <Typography variant="body2" noWrap sx={{ maxWidth: 160 }}>
                      {building.building_id}
                    </Typography>
                    <Typography variant="caption" color="text.secondary" sx={{ ml: "auto" }}>
                      {building.image_count}
                    </Typography>
                  </Box>
                }
              >
                {/* Image leaves — populated when building detail is loaded */}
                <TreeItem
                  itemId={`img-placeholder:${building.building_id}`}
                  label={
                    <Box sx={{ display: "flex", alignItems: "center", gap: 0.5, py: 0.25 }}>
                      <CropOriginalOutlined fontSize="small" color="disabled" />
                      <Typography variant="caption" color="text.secondary">
                        Select building to load images
                      </Typography>
                    </Box>
                  }
                />
              </TreeItem>
            ))
          )}
        </TreeItem>
      ))}
    </SimpleTreeView>
  );
}

