                  >
                    <ApartmentOutlined fontSize="small" color="action" />
                    <Typography variant="body2" noWrap sx={{ maxWidth: 160 }}>
                      {building.building_id}
                    </Typography>
                    <Typography variant="caption" color="text.secondary" sx={{ ml: "auto" }}>
                      {building.image_count}
                    </Typography>
                  </Box>
                }
              />
            ))
          )}
        </TreeItem>
      ))}
    </SimpleTreeView>
  );
}

