            setFilter(e.target.value);
            setScrollTop(0);
            if (containerRef.current) containerRef.current.scrollTop = 0;
          }}
          slotProps={{
            input: {
              startAdornment: (
                <InputAdornment position="start">
                  <SearchOutlined fontSize="small" />
                </InputAdornment>
              ),
            },
          }}
          sx={{ mb: 0.5, width: "100%" }}
        />
      )}

      {/* Scroll container */}
      <Box
        ref={containerRef}
        onScroll={(e) => setScrollTop((e.currentTarget as HTMLDivElement).scrollTop)}
        sx={{
          height: Math.min(CONTAINER_HEIGHT, filtered.length * ITEM_HEIGHT) || ITEM_HEIGHT,
          overflowY: "auto",
          position: "relative",
        }}
      >
        {/* Spacer to give the scrollbar the correct total height */}
        <Box sx={{ height: totalHeight, position: "relative" }}>
