{"content": "/**
 * Recharts-based training curves.
 * Each selected run gets its own line colour, derived from a stable palette.
 */
import {
  CartesianGrid,
  Legend,
  Line,
  LineChart,
  ReferenceLine,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { Box, Typography } from "@mui/material";
import type { EpochRecord } from "@/types";

// Stable palette — first 8 colours
const PALETTE = [
  "#2196f3",
  "#f44336",
  "#4caf50",
  "#ff9800",
  "#9c27b0",
  "#00bcd4",
  "#795548",
  "#607d8b",
];

export type RunHistoryMap = Record<string, EpochRecord[]>;

// All tasks that can appear in per-task metric charts
const PHASE1_TASKS = ["stories", "roof_type", "primary_cladding", "chimney_present", "setting"];

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Build a per-epoch series for a single scalar field across multiple runs. */
function buildSeries(
  histories: RunHistoryMap,
  getVal: (e: EpochRecord) => number
): Array<Record<string, number>> {
  // Determine max epoch
  const maxEpoch = Math.max(
    ...Object.values(histories).map((h) => (h.length > 0 ? h[h.length - 1].epoch : 0))
  );
  const rows: Array<Record<string, number>> = [];
  for (let ep = 1; ep <= maxEpoch; ep++) {
    const row: Record<string, number> = { epoch: ep };
    for (const [runId, history] of Object.entries(histories)) {
      const rec = history.find((e) => e.epoch === ep);
      if (rec !== undefined) row[runId] = getVal(rec);
    }
    rows.push(row);
  }
  return rows;
}

function runLabel(runId: string) {
  // Shorten: strip leading "data2/" or "data/"
  return runId.replace(/^[^/]+\//, "");
}

// ---------------------------------------------------------------------------
// Shared chart wrapper
// ---------------------------------------------------------------------------

interface ChartProps {
  title: string;
  data: Array<Record<string, number>>;
  runIds: string[];
  yLabel?: string;
  yFormatter?: (v: number) => string;
  domain?: [number | "auto", number | "auto"];
}

function TrainingChart({
  title,
  data,
  runIds,
  yLabel,
  yFormatter,
  domain,
}: ChartProps) {
  if (data.length === 0 || runIds.length === 0) return null;
  return (
    <Box sx={{ mb: 4 }}>
      <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
        {title}
      </Typography>
      <ResponsiveContainer width="100%" height={260}>
        <LineChart data={data} margin={{ top: 4, right: 24, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
          <XAxis
            dataKey="epoch"
            label={{ value: "Epoch", position: "insideBottom", offset: -2, fontSize: 11 }}
            tick={{ fontSize: 11 }}
          />
          <YAxis
            tickFormatter={yFormatter}
            label={
              yLabel
                ? { value: yLabel, angle: -90, position: "insideLeft", fontSize: 11 }
                : undefined
            }
            tick={{ fontSize: 11 }}
            domain={domain}
          />
          <Tooltip
            formatter={(val: number, name: string) => [
              yFormatter ? yFormatter(val) : val.toFixed(4),
              runLabel(name),
            ]}
            labelFormatter={(ep) => `Epoch ${ep}`}
          />
          <Legend
            formatter={(value) => runLabel(value)}
            wrapperStyle={{ fontSize: 11 }}
          />
          {runIds.map((runId, i) => (
            <Line
              key={runId}
              type="monotone"
              dataKey={runId}
              stroke={PALETTE[i % PALETTE.length]}
              dot={false}
              strokeWidth={2}
              connectNulls
            />
          ))}
        </LineChart>
      </ResponsiveContainer>
    </Box>
  );
}

// ---------------------------------------------------------------------------
// Train vs Val loss — one chart per run (two lines each)
// ---------------------------------------------------------------------------

interface LossChartProps {
  runId: string;
  history: EpochRecord[];
  color: string;
}

export function LossChart({ runId, history, color }: LossChartProps) {
  const data = history.map((e) => ({
    epoch: e.epoch,
    train: e.train_loss_total,
    val: e.val_loss_total,
  }));
  return (
    <Box sx={{ mb: 3 }}>
      <Typography variant="subtitle2" sx={{ mb: 0.5, fontWeight: 600 }}>
        Loss — {runLabel(runId)}
      </Typography>
      <ResponsiveContainer width="100%" height={220}>
        <LineChart data={data} margin={{ top: 4, right: 24, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
          <XAxis dataKey="epoch" tick={{ fontSize: 11 }} />
          <YAxis tick={{ fontSize: 11 }} />
          <Tooltip labelFormatter={(ep) => `Epoch ${ep}`} />
          <Legend wrapperStyle={{ fontSize: 11 }} />
          <Line
            type="monotone"
            dataKey="train"
            name="Train Loss"
            stroke={color}
            dot={false}
            strokeWidth={2}
          />
          <Line
            type="monotone"
            dataKey="val"
            name="Val Loss"
            stroke={color}
            dot={false}
            strokeWidth={2}
            strokeDasharray="5 3"
          />
        </LineChart>
      </ResponsiveContainer>
    </Box>
  );
}

// ---------------------------------------------------------------------------
// Overall accuracy across runs
// ---------------------------------------------------------------------------

export function AccuracyChart({ histories }: { histories: RunHistoryMap }) {
  const runIds = Object.keys(histories);
  const data = buildSeries(histories, (e) => e.overall_accuracy * 100);
  return (
    <TrainingChart
      title="Overall Accuracy (val)"
      data={data}
      runIds={runIds}
      yLabel="%"
      yFormatter={(v) => `${v.toFixed(1)}%`}
      domain={[0, 100]}
    />
  );
}

// ---------------------------------------------------------------------------
// Per-task accuracy across runs
// ---------------------------------------------------------------------------

export function TaskAccuracyCharts({ histories }: { histories: RunHistoryMap }) {
  const runIds = Object.keys(histories);
  // Determine which tasks are present
  const tasks = new Set<string>();
  for (const history of Object.values(histories)) {
    for (const e of history) {
      for (const task of PHASE1_TASKS) {
        if (e.val_metrics[task]) tasks.add(task);
      }
    }
  }

  return (
    <>
      {Array.from(tasks).map((task) => {
        const data = buildSeries(histories, (e) => {
          const m = e.val_metrics[task];
          if (!m || typeof m === "number") return 0;
          return (m.acc ?? m.exact ?? 0) * 100;
        });
        return (
          <TrainingChart
            key={task}
            title={`${task} — accuracy (val)`}
            data={data}
            runIds={runIds}
            yFormatter={(v) => `${v.toFixed(1)}%`}
            domain={[0, 100]}
          />
        );
      })}
    </>
  );
}

// ---------------------------------------------------------------------------
// Per-task F1 across runs
// ---------------------------------------------------------------------------

export function TaskF1Charts({ histories }: { histories: RunHistoryMap }) {
  const runIds = Object.keys(histories);
  const tasks = new Set<string>();
  for (const history of Object.values(histories)) {
    for (const e of history) {
      for (const task of PHASE1_TASKS) {
        if (e.val_metrics[task]) tasks.add(task);
      }
    }
  }

  return (
    <>
      {Array.from(tasks).map((task) => {
        const data = buildSeries(histories, (e) => {
          const m = e.val_metrics[task];
          if (!m || typeof m === "number") return 0;
          return (m.f1 ?? 0) * 100;
        });
        return (
          <TrainingChart
            key={task}
            title={`${task} — macro F1 (val)`}
            data={data}
            runIds={runIds}
            yFormatter={(v) => `${v.toFixed(1)}%`}
            domain={[0, 100]}
          />
        );
      })}
    </>
  );
}
