import {
  Box,
  Divider,
  Tab,
  Tabs,
  Typography,
} from "@mui/material";
import { AppShell } from "@/components/layout/AppShell";
import { RunSelector } from "@/components/training/RunSelector";
import {
  AccuracyChart,
  LossChart,
  TaskAccuracyCharts,
  TaskF1Charts,
  type RunHistoryMap,
} from "@/components/training/TrainingCharts";
import { RunCompareTable } from "@/components/training/RunCompareTable";
import { api } from "@/api/client";
import type { EpochRecord, RunInfo } from "@/types";

const PALETTE = [
  "#2196f3", "#f44336", "#4caf50", "#ff9800",
  "#9c27b0", "#00bcd4", "#795548", "#607d8b",
];

export default function TrainingEvaluationPage() {
  const [runs, setRuns] = useState<RunInfo[]>([]);
  const [loadingRuns, setLoadingRuns] = useState(true);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [histories, setHistories] = useState<Record<string, EpochRecord[]>>({});
  const [tab, setTab] = useState(0);

  // Load run list on mount
  useEffect(() => {
    api
      .listRuns()
      .then((data) => {
        setRuns(data);
        // Auto-select the most recent run if none selected
        if (data.length > 0) {
          const latest = [...data].sort((a, b) =>
            b.timestamp.localeCompare(a.timestamp)
          )[0];
          setSelectedIds(new Set([latest.run_id]));
        }
      })
      .finally(() => setLoadingRuns(false));
  }, []);

  // Fetch history for newly selected runs
  useEffect(() => {
    for (const runId of selectedIds) {
      if (!histories[runId]) {
        api.getRunHistory(runId).then((h) => {
          setHistories((prev) => ({ ...prev, [runId]: h }));
        });
      }
    }
  }, [selectedIds]); // eslint-disable-line react-hooks/exhaustive-deps

