export function formatRunLabel(runId: string, runLabels?: Record<string, string>): string {
  return runLabels?.[runId] ?? runId.replace(/^[^/]+\//, "");
}

/**
 * Build version-based labels for a set of runs:
 *   first run per backbone  → "{backbone}_v1"
 *   subsequent runs         → "{backbone}_v{N}_{changed_params}"
 * Params compared vs the backbone's v1 baseline: lr, weight_decay, batch_size.
 */
export function buildRunLabels(runs: RunInfo[]): Record<string, string> {
  const sorted = [...runs].sort((a, b) => a.timestamp.localeCompare(b.timestamp));

  const byBackbone: Record<string, RunInfo[]> = {};
  for (const run of sorted) {
    (byBackbone[run.backbone] ??= []).push(run);
  }

  const labels: Record<string, string> = {};
  for (const [backbone, group] of Object.entries(byBackbone)) {
    const baseline = group[0];
    group.forEach((run, i) => {
      if (i === 0) {
        labels[run.run_id] = `${backbone}_v1`;
      } else {
        const changed: string[] = [];
        if (run.lr !== baseline.lr) changed.push(`lr${run.lr.toExponential(0)}`);
        if (run.weight_decay !== baseline.weight_decay) changed.push(`wd${run.weight_decay}`);
        if (run.batch_size !== baseline.batch_size) changed.push(`bs${run.batch_size}`);
        const suffix = changed.length > 0 ? `_${changed.join("_")}` : "";
        labels[run.run_id] = `${backbone}_v${i + 1}${suffix}`;
      }
    });
  }
  return labels;
}

