function ChartDataTable({
  data,
  columns,
}: {
  data: Array<Record<string, number>>;
  columns: ColDef[];
}) {
  const rows = data.filter((row) =>
    columns.some((c) => c.key !== "epoch" && row[c.key] != null)
  );
  return (
    <TableContainer
      component={Paper}
      variant="outlined"
      sx={{ maxHeight: 320, overflowX: "auto", overflowY: "auto" }}
    >
      <Table size="small" stickyHeader>
        <TableHead>
          <TableRow>
            {columns.map((col) => (
              <TableCell
                key={col.key}
                sx={{ fontSize: 11, fontWeight: 600, whiteSpace: "nowrap", minWidth: 64 }}
              >
                {col.header}
              </TableCell>
            ))}
          </TableRow>
        </TableHead>
        <TableBody>
          {rows.map((row) => (
            <TableRow key={row.epoch} hover>
              {columns.map((col) => {
                const val = row[col.key];
                return (
                  <TableCell key={col.key} sx={{ fontSize: 11, whiteSpace: "nowrap" }}>
                    {val == null
                      ? "—"
                      : col.format
                      ? col.format(val)
                      : typeof val === "number"
                      ? val.toFixed(4)
                      : val}
                  </TableCell>
                );
              })}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
}

